<template>
  <div class="er-root">
    <p v-if="error" class="er-alert danger" role="alert">{{ error }}</p>
    <p v-if="notice" class="er-alert" role="status">{{ notice }}</p>
    <p v-if="loading" role="status">正在读取服务信息…</p>

    <template v-if="['care','onboarding','support'].includes(mode) && !loading">
      <div class="er-intro"><div><span class="er-kicker">陪伴每一个重要阶段</span><h2>{{ mode === 'support' ? '支持与关怀咨询' : (weekly ? '本周工作计划' : '入职与成长导航') }}</h2><p>{{ mode === 'support' ? '整理当下的困扰，找到可行的下一步和实际支持渠道。' : (weekly ? '把一周的工作安排清楚，按实际进展勾选完成。' : '按阶段准备，展开每项任务查看操作步骤。完成进度会保存到你的账号。') }}</p></div><span class="er-symbol">☀</span></div>
      <div v-if="mode !== 'support'" class="er-switch"><button v-for="p in [journeyLabel,'离职准备']" :key="p" :class="{ active: careTab === p || (p === journeyLabel && careTab !== '离职准备') }" @click="careTab = p">{{ p }}</button></div>
      <template v-if="careTab !== '压力与关怀'">
        <p v-if="weekly && careTab !== '离职准备'" class="er-muted">本周起始日：{{ tasks.find(t => t.phase === '本周')?.key.slice(7, 17) }}（周一）</p>
        <div class="er-progress"><strong>{{ completed }} / {{ visibleTasks.length }} 项已完成</strong><span>进度为个人准备记录</span><progress :value="completed" :max="visibleTasks.length || 1" aria-label="个人准备进度" /></div>
        <p class="er-muted">{{ careTab === '离职准备' ? '这里不会提交辞职或自动停用账号。离职时间、社保减员和结算请与 HR 核对。' : (weekly ? '按周一至周日记录，每周自动开启新清单。仅供个人安排，不用于考勤或绩效评价。' : '适用于入职前及入职前 30 天，之后自动切换每周计划；具体安排以团队和 HR 通知为准。') }}</p>
        <label v-if="!weekly && careTab !== '离职准备'" class="er-phase-filter">查看阶段 <select v-model="phase"><option>全部阶段</option><option>第一天</option><option>第一周</option><option>第一个月</option></select></label>
        <article v-for="task in visibleTasks" :key="task.key" class="er-task" :class="{ done: task.done }"><div class="er-task-content"><label class="er-task-heading"><input type="checkbox" :checked="task.done" :disabled="busy" @change="toggleTask(task, $event)" /><span><small>{{ task.phase }}<span v-if="task.dueDate"> · 建议 {{ task.dueDate }}</span></small><strong>{{ task.title }}</strong></span></label><p>{{ task.detail }}</p><details><summary>展开行动指引</summary><ol><li v-for="step in (journeyGuidance[task.key]?.steps || [task.detail])" :key="step">{{ step }}</li></ol><a v-if="journeyGuidance[task.key] && task.key !== 'week-culture'" :href="workbenchUrl + journeyGuidance[task.key]!.path">{{ journeyGuidance[task.key]!.action }} →</a><p class="er-muted">按实际准备情况勾选完成；展开指引不会自动完成任务。</p></details></div></article>
        <WorkplaceTools v-if="careTab !== '离职准备'" :request="props.request" />
        <article v-else class="er-card"><h3>愿意聊聊你的离职经历吗？</h3><p>你可以只回答愿意分享的部分：哪些经历促成了决定？管理协作、薪酬或发展中，最希望改变什么？哪些支持对你有帮助？</p><p>访谈自愿参与，采用与申诉相同的加密工单流程。可以匿名；不是保密于所有基础设施的承诺。</p><button class="er-primary" @click="startInterview">开始自愿离职访谈</button></article>
      </template>
      <template v-else>
        <CareWorkspace :request="props.request" />
        <EmployeePulse :request="props.request" />

        <div class="er-grid"><article class="er-card"><span class="er-kicker">企业支持</span><h3>{{ resources?.eapName || '企业 EAP 心理支持' }}</h3><p v-if="!resources?.eapPhone && !resources?.eapUrl">企业暂未维护预约渠道，请向 HR 了解实际服务。</p><p v-if="resources?.eapPhone">咨询电话：{{ resources.eapPhone }}</p><a v-if="safeUrl(resources?.eapUrl)" :href="resources?.eapUrl" target="_blank" rel="noopener noreferrer">前往预约 ↗</a><p class="er-muted">保密范围、费用和服务时段以提供方说明为准。</p></article><article class="er-card"><span class="er-kicker">公共支持 · 中国大陆</span><h3><a href="tel:12356">12356 心理援助热线</a></h3><p>如有眼前人身危险，请立即联系当地急救或警方，在中国大陆可拨 120 / 110，并请可信任的人陪伴。</p><a :href="hotlineSource" target="_blank" rel="noopener noreferrer">国家卫生健康委来源 ↗</a><p class="er-muted">不要等待内部工单处理紧急情况。</p></article></div>
      </template>
    </template>

    <template v-if="mode === 'compliance' || interviewOpen">
      <div class="er-intro"><div><span class="er-kicker">认真对待每一份声音</span><h2>{{ interviewOpen ? '你的经历，值得被听见。' : '可以咨询，也可以提出申诉。' }}</h2><p>以事实为起点，按你的意愿选择实名或匿名。</p></div><span class="er-tag">加密保存 · 指定人员处理</span></div>
      <p class="er-alert" v-if="resources && !resources.routingReady">企业尚未指定调查人员，暂不接收敏感工单。{{ resources.erContact ? `ER 联系方式：${resources.erContact}` : '请向企业公布的 HR、合规负责人或外部主管部门求助。' }}</p>
      <details class="er-card" :open="interviewOpen"><summary>{{ interviewOpen ? '填写自愿访谈' : '填写申诉 / 申请 ER 咨询' }}</summary>
        <form class="er-form" @submit.prevent="submitCase">
          <div class="er-grid"><label>事项类型<select v-model="form.kind"><option value="COMPLAINT">职场不公与违规申诉</option><option value="CONSULT">劳动关系专业咨询</option><option value="EXIT_INTERVIEW">自愿离职访谈</option></select></label><label>提交方式<select v-model="form.anonymous"><option :value="true">匿名 · 凭查询码跟进</option><option :value="false">实名 · 关联本人账号</option></select></label></div>
          <p class="er-muted">{{ form.anonymous ? '匿名工单不保存账号关联，正文与回复加密。内容中的姓名、时间细节以及登录和基础设施日志仍可能识别身份；请勿填写不必要的身份信息。查询码仅显示一次，遗失无法按账号找回。' : '实名工单包含你的员工身份，正文仅本企业指定调查人员可见。主管没有默认查阅权限。' }}</p>
          <div class="er-grid"><label>发生时间（可选）<input v-model.trim="form.occurredAt" maxlength="160" placeholder="不确定可写大致时间" /></label><label>发生地点（可选）<input v-model.trim="form.location" maxlength="240" placeholder="办公室、线上会议等" /></label></div>
          <label>{{ form.kind === 'EXIT_INTERVIEW' ? '你愿意分享的经历' : '事实描述' }}<textarea v-model.trim="form.facts" required minlength="2" maxlength="4000" rows="5" placeholder="发生了什么？哪些是亲历事实，哪些需要进一步核实？只写你愿意分享的内容。" /></label>
          <label>证据或证人线索（可选）<textarea v-model.trim="form.evidence" maxlength="2000" rows="2" placeholder="可描述已有材料及安全获取方式；不需要提供无关人员的个人信息。" /></label>
          <label>希望获得的帮助（可选）<textarea v-model.trim="form.expectation" maxlength="1000" rows="2" placeholder="例如：了解处理流程、核实事实、安排沟通。" /></label>
          <label class="er-check"><input v-model="form.consent" type="checkbox" required />我已阅读上方隐私说明，自愿将这些内容交由企业指定调查人员处理。</label>
          <p class="er-muted">紧急危险请直接求助；提交不代表已有人在线。内部申诉不影响向外部主管部门求助。聊天触发明显安全风险或现实争议时，可创建实名支持工单并暂停自动办理。</p>
          <button class="er-primary" :disabled="busy || !resources?.routingReady || !form.consent">{{ busy ? '保存中…' : '确认提交' }}</button>
        </form>
      </details>
      <article v-if="receipt" class="er-receipt" role="status"><h3>请立即保存匿名查询码</h3><p class="er-code">{{ receipt }}</p><button class="er-primary" @click="downloadReceipt">下载查询凭证</button><p>此页面关闭后不再显示；系统不在浏览器中保存查询码。</p></article>
      <div class="er-row"><h3>我的工单与人工回复</h3><button class="er-outline" :disabled="busy" @click="loadCases">刷新状态</button></div>
      <form class="er-lookup" @submit.prevent="lookup"><label>匿名查询码<input v-model.trim="lookupCode" maxlength="100" autocomplete="off" placeholder="粘贴提交时保存的查询码" required /></label><button class="er-outline" :disabled="busy">查询匿名工单</button></form>
      <p v-if="!loading && !error && !displayedCases.length" class="er-empty" role="status">暂无可显示的工单。提交实名工单后，可在这里查看内容和处理进度；匿名工单请使用提交时保存的查询码查询。</p>
      <article v-for="item in displayedCases" :key="item.id" class="er-card"><div class="er-row"><h3>#{{ item.id }} · {{ kindLabel(item.kind) }}</h3><span class="er-tag">{{ statusLabel(item.status) }}</span></div><p class="er-muted">{{ item.anonymous ? '匿名' : '实名' }} · {{ formatDate(item.updatedAt) }}</p><details><summary>查看已提交内容</summary><p class="er-pre">{{ item.facts }}</p></details><p class="er-pre">{{ item.reply || '尚无人工回复。此处不是实时聊天，紧急事项请使用直接求助渠道。' }}</p><form class="er-form" @submit.prevent="followup(item)"><label>补充说明<textarea v-model.trim="followups[item.id]" maxlength="2000" rows="2" required /></label><button class="er-outline" :disabled="busy">补充到工单</button></form></article>
      <div class="er-grid"><details v-for="guide in legalGuides" :key="guide.key" class="er-card"><summary>{{ guide.title }}</summary><p class="er-pre">{{ guide.content }}</p><p class="er-muted">{{ guide.source }} · 核验 {{ guide.verifiedAt }}</p><a v-if="safeUrl(guide.url)" :href="guide.url" target="_blank" rel="noopener noreferrer">查阅原文 ↗</a></details></div>
    </template>

    <template v-if="mode === 'operations' && user.role === 'HR'">
      <div class="er-intro"><div><span class="er-kicker">HR & 组织运营</span><h2>看见共性问题，改善员工体验。</h2><p>把服务缺口变成可跟进的行动，让关怀有依据、有边界。</p></div><button class="er-outline" :disabled="busy" @click="loadOperations">刷新后台</button></div>
      <div class="er-switch"><button v-for="p in ['组织洞察','员工反馈','知识待办','人工队列','服务配置']" :key="p" :class="{ active: opsTab === p }" @click="opsTab = p">{{ p }}</button></div>
      <EmployeePulse v-if="opsTab === '员工反馈'" :request="props.request" admin />
      <template v-if="opsTab === '组织洞察'"><p class="er-alert">{{ insights?.privacyNote }}</p><p class="er-muted">统计周期：{{ insights?.since }} 起。本周尚未结束，与上周的比较仅作关注提示。</p><div v-if="!insights?.topics.length" class="er-empty"><h3>暂时没有达到展示门槛的团队主题</h3><p>每个部门的单个主题至少需要 5 位自愿参与者。样本不足时不显示人数和风险结论。</p></div><article v-for="metric in insights?.topics" :key="metric.department + metric.topic" class="er-card"><div class="er-row"><strong>{{ metric.department }} · {{ metric.topic }}</strong><span>{{ metric.participants }} 位参与者</span></div><progress :value="metric.participants" :max="maxParticipants" :aria-label="`${metric.topic}咨询人数`" /><p>{{ metric.trend }}</p><small>{{ metric.previousParticipants < 0 ? '上周未达隐私门槛' : `上周 ${metric.previousParticipants} 位参与者` }}</small></article><p class="er-muted">离职相关主题仅反映咨询需求，不等同于实际离职倾向；不会生成个人风险名单。</p></template>
      <template v-if="opsTab === '知识待办'"><div class="er-row"><p>自动聚合同类未决问题，仅保存主题和次数，不保存咨询原文。</p><button class="er-outline" :disabled="busy" @click="seedDrafts">补充服务知识草稿</button></div><p v-if="!gaps.length" class="er-empty">暂时没有未决主题。缺失的适用制度和员工反馈会进入这里。</p><article v-for="gap in gaps" :key="gap.id" class="er-card"><div class="er-row"><strong>{{ gap.topic }}</strong><span class="er-tag">{{ gap.status === 'OPEN' ? '待 HR 补充' : '已核实' }}</span></div><p>{{ gap.occurrences }} 次待解决记录 · 最近 {{ formatDate(gap.updatedAt) }}</p><div class="er-row"><a :href="workbenchUrl + '/knowledge'" target="_blank" rel="noopener noreferrer">维护知识库 ↗</a><button class="er-outline" :disabled="busy" @click="resolveGap(gap)">{{ gap.status === 'OPEN' ? '标记已核实' : '重新打开' }}</button></div></article><p class="er-muted">新增草稿需要核实原文、适用范围和生效日期，并经 HR 审核后才能作为制度依据。标记待办已核实不会自动发布制度。</p></template>
      <template v-if="opsTab === '人工队列'"><p v-if="!resources?.investigator" class="er-empty">仅企业指定的调查人员可访问。普通 HR 和主管没有默认的工单查阅权限。</p><template v-else><p v-if="!queue.length" class="er-empty">当前没有工单。</p><button v-for="item in queue" :key="item.id" class="er-queue" @click="openCase(item.id)" :disabled="busy"><strong>#{{ item.id }} · {{ kindLabel(item.kind) }}</strong><span>{{ item.anonymous ? '匿名' : '实名' }} · {{ statusLabel(item.status) }}</span></button><article v-if="selectedCase" class="er-card"><h3>#{{ selectedCase.id }} · {{ selectedCase.employee }}</h3><p class="er-muted">本次查阅已记录审计日志。请先核实事实、利益冲突和所需支持。</p><p class="er-pre">{{ selectedCase.facts }}</p><p class="er-pre">{{ selectedCase.reply }}</p><form v-if="selectedCase.status !== 'RESOLVED'" class="er-form" @submit.prevent="processCase"><label>发送给员工的人工回复<textarea v-model.trim="caseReply" required maxlength="3000" rows="4" /></label><label>处理状态<select v-model="caseStatus"><option value="IN_PROGRESS">接单并继续处理</option><option value="RESOLVED">发送回复并结案</option></select></label><button class="er-primary" :disabled="busy">保存人工回复</button></form></article></template></template>
      <form v-if="opsTab === '服务配置' && settings" class="er-form" @submit.prevent="saveSettings"><div class="er-grid"><label>EAP 服务名称<input v-model.trim="settings.eapName" maxlength="160" /></label><label>EAP 咨询电话<input v-model.trim="settings.eapPhone" maxlength="80" /></label></div><label>EAP 预约地址<input v-model.trim="settings.eapUrl" type="url" maxlength="1000" placeholder="https://…" /></label><label>企业 ER 联系方式<input v-model.trim="settings.erContact" maxlength="500" placeholder="员工实际可联系的渠道、时段与联系人" /></label><fieldset><legend>指定 ER 调查人员</legend><p class="er-muted">所选人员可读取企业全部申诉和人工支持工单，请根据调查职责授权。变更会进入审计日志。</p><label v-for="employee in hrEmployees" :key="employee.id" class="er-check"><input v-model="settings.investigatorIds" :value="employee.id" type="checkbox" />{{ employee.name }} · {{ employee.employeeNo }}</label></fieldset><button class="er-primary" :disabled="busy">保存服务配置</button></form>
    </template>

    <details class="er-privacy"><summary>我的数据与隐私选择</summary><p>申诉和心理支持不用于组织主题分析。默认不采集你的咨询主题；如自愿开启，仅按周保存部门、主题和不可直接识别你的标记。每个部门主题至少 5 人才展示，可随时撤回并删除最近 8 周的主题标记。</p><label class="er-check"><input type="checkbox" :checked="resources?.analyticsEnabled" :disabled="busy || !resources" @change="toggleConsent" />自愿参与匿名汇总的服务需求分析</label><p>工单正文加密保存，仅指定调查人员可查看。聊天历史可能保存在当前设备；涉及匿名内容，请使用申诉表单。</p></details>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, defineAsyncComponent } from 'vue'
const EmployeePulse = defineAsyncComponent(() => import('./EmployeePulse.vue'))
import WorkplaceTools from './WorkplaceTools.vue'
import CareWorkspace from './CareWorkspace.vue'
import { journeyGuidance } from './journeyGuidance'
type Request = (path: string, options?: { method?: string; body?: unknown; binary?: boolean }) => Promise<any>
interface Resources { eapName: string; eapPhone: string; eapUrl: string; erContact: string; routingReady: boolean; investigator: boolean; analyticsEnabled: boolean }
interface Task { key: string; phase: string; title: string; detail: string; done: boolean; dueDate: string }
interface Case { id: number; kind: string; status: string; anonymous: boolean; employee: string; facts: string; reply: string; assignedTo: number; updatedAt: string }
interface Guide { key: string; title: string; content: string; source: string; url: string; verifiedAt: string }
interface Gap { id: number; topic: string; occurrences: number; status: string; updatedAt: string }
interface Settings { eapName: string; eapPhone: string; eapUrl: string; erContact: string; investigatorIds: number[] }
interface Insights { since: string; privacyNote: string; topics: { department: string; topic: string; participants: number; previousParticipants: number; trend: string }[] }
const props = defineProps<{ mode: string; user: { id: number; name: string; role?: string }; request: Request; workbenchUrl: string }>()
const resources = ref<Resources>(), tasks = ref<Task[]>([]), guides = ref<Guide[]>([]), myCases = ref<Case[]>([]), anonymousCase = ref<Case>(), queue = ref<Case[]>([]), selectedCase = ref<Case>(), gaps = ref<Gap[]>([]), settings = ref<Settings>(), insights = ref<Insights>()
const employees = ref<{ id: number; role: string; name: string; employeeNo: string }[]>([])
const loading = ref(false), busy = ref(false), error = ref(''), notice = ref(''), receipt = ref(''), lookupCode = ref(''), careTab = ref(props.mode === 'support' ? '压力与关怀' : '入职导航'), opsTab = ref('组织洞察'), interviewOpen = ref(false), caseReply = ref(''), caseStatus = ref('IN_PROGRESS')
const followups = reactive<Record<number, string>>({})
const form = reactive({ kind: 'COMPLAINT', anonymous: true, facts: '', occurredAt: '', location: '', evidence: '', expectation: '', consent: false })
const hotlineSource = 'https://www.nhc.gov.cn/xcs/c100122/202512/9731f93a7e0d451284a0da462527cbd2.shtml'
if (new URLSearchParams(window.location.search).get('journey') === 'exit' && props.mode !== 'support') careTab.value = '离职准备'
const phase = ref('全部阶段')
const visibleTasks = computed(() => tasks.value.filter(t => (t.phase === '离职准备') === (careTab.value === '离职准备')).filter(t => careTab.value === '离职准备' || phase.value === '全部阶段' || t.phase === phase.value))
const weekly = computed(() => tasks.value.some(t => t.phase === '本周'))
const journeyLabel = computed(() => weekly.value ? '每周计划' : '入职导航')
const completed = computed(() => visibleTasks.value.filter(t => t.done).length)
const legalGuides = computed(() => guides.value.filter(g => ['noncompete','injury','change'].includes(g.key)))
const displayedCases = computed(() => anonymousCase.value ? [anonymousCase.value, ...myCases.value] : myCases.value)
const hrEmployees = computed(() => employees.value.filter(e => e.role === 'HR'))
const maxParticipants = computed(() => Math.max(5, ...(insights.value?.topics.map(m => m.participants) || [])))
const request = (path: string, method?: string, body?: unknown) => props.request('/employee-relations' + path, { method, body })
function safeUrl(value?: string) { try { const url = new URL(value || ''); return ['http:','https:'].includes(url.protocol) && !url.username && !url.password } catch { return false } }
function formatDate(value: string) { return value?.replace('T', ' ').slice(0, 16) || '—' }
function statusLabel(value: string) { return ({ OPEN:'待人工接单', IN_PROGRESS:'人工处理中', RESOLVED:'已结案' } as Record<string,string>)[value] || value }
function kindLabel(value: string) { return ({ COMPLAINT:'合规申诉', CONSULT:'专业咨询', EXIT_INTERVIEW:'自愿离职访谈', URGENT:'紧急支持', HANDOFF:'人工介入' } as Record<string,string>)[value] || value }
async function run(action: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await action() } catch(e: any) { error.value = e.response?.data?.message || e.message || '操作失败，请稍后再试' } finally { busy.value = false } }
async function refreshCases() { myCases.value = await request('/cases') }
async function loadCases() { await run(refreshCases) }
async function toggleTask(task: Task, event: Event) { (event.target as HTMLInputElement).checked = task.done; await run(async () => { tasks.value = await request('/journey/' + task.key, 'PUT', { enabled: !task.done }) }) }
function startInterview() { form.kind = 'EXIT_INTERVIEW'; interviewOpen.value = true }
async function submitCase() { await run(async () => { const result = await request('/cases', 'POST', form); receipt.value = result.receipt || ''; anonymousCase.value = form.anonymous ? result.caseInfo : undefined; lookupCode.value = receipt.value; notice.value = result.message; form.facts = ''; form.evidence = ''; form.expectation = ''; form.occurredAt = ''; form.location = ''; form.consent = false; await refreshCases() }) }
async function lookup() { await run(async () => { anonymousCase.value = undefined; anonymousCase.value = await request('/cases/lookup', 'POST', { receipt: lookupCode.value }) }) }
async function followup(item: Case) { await run(async () => { const updated = await request(`/cases/${item.id}/followup`, 'POST', { message: followups[item.id], receipt: item.anonymous ? lookupCode.value : null }); if (item.anonymous) anonymousCase.value = updated; else await refreshCases(); followups[item.id] = ''; notice.value = '补充已加密保存。' }) }
function downloadReceipt() { const url = URL.createObjectURL(new Blob([`HRAgent 匿名工单查询凭证\n工单：#${anonymousCase.value?.id}\n查询码：${receipt.value}\n请妥善保管，持有人可查看和补充工单。\n入口：${props.workbenchUrl}/employee-services`], { type: 'text/plain;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = '匿名工单查询凭证.txt'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function fetchOperations() { const results = await Promise.allSettled([request('/hr/insights'), request('/hr/gaps'), request('/hr/settings'), props.request('/admin/employees')]); const assign = [(v:any) => insights.value=v, (v:any) => gaps.value=v, (v:any) => settings.value=v, (v:any) => employees.value=v]; results.forEach((r,i) => { if(r.status === 'fulfilled') assign[i]!(r.value); else error.value = '部分后台数据暂时无法加载，请刷新重试。' }); if (resources.value?.investigator) queue.value = await request('/hr/cases') }
async function loadOperations() { await run(fetchOperations) }
async function openCase(id: number) { await run(async () => { selectedCase.value = undefined; selectedCase.value = await request('/hr/cases/' + id); caseReply.value = ''; caseStatus.value = 'IN_PROGRESS' }) }
async function processCase() { await run(async () => { if (!selectedCase.value) return; selectedCase.value = await request(`/hr/cases/${selectedCase.value.id}`, 'PATCH', { status: caseStatus.value, reply: caseReply.value }); caseReply.value = ''; queue.value = await request('/hr/cases'); notice.value = '人工回复已保存，员工可在工单中查看。' }) }
async function saveSettings() { await run(async () => { settings.value = await request('/hr/settings', 'PUT', settings.value); resources.value = await request('/resources'); queue.value = resources.value?.investigator ? await request('/hr/cases') : []; selectedCase.value = undefined; notice.value = '服务渠道与调查人员配置已保存。' }) }
async function resolveGap(gap: Gap) { await run(async () => { await request('/hr/gaps/' + gap.id, 'PATCH', { status: gap.status === 'OPEN' ? 'RESOLVED' : 'OPEN' }); gaps.value = await request('/hr/gaps') }) }
async function seedDrafts() { await run(async () => { const count = await request('/hr/knowledge-drafts', 'POST'); notice.value = `已添加 ${count} 条知识草稿。请到知识库核实并审核。` }) }
async function toggleConsent(event: Event) { const checkbox = event.target as HTMLInputElement; const enabled=checkbox.checked; checkbox.checked=resources.value?.analyticsEnabled || false; await run(async () => { resources.value = await request('/analytics-consent', 'PUT', { enabled }); notice.value = enabled ? '已开启自愿参与，可随时撤回。' : '已关闭参与并删除最近 8 周的主题标记。' }) }
onMounted(async () => { loading.value = true; await run(async () => { const results = await Promise.allSettled([request('/resources'), request('/journey'), request('/guides'), request('/cases')]); const assign = [(v:any) => resources.value=v,(v:any) => tasks.value=v,(v:any) => guides.value=v,(v:any) => myCases.value=v]; results.forEach((r,i) => { if(r.status === 'fulfilled') assign[i]!(r.value); else error.value = '部分服务暂不可用，请稍后重试。' }); if (props.mode === 'operations' && props.user.role === 'HR') await fetchOperations() }); loading.value = false })
</script>

